Lemma KB_apop_eq : forall s ch,
  enq_is_app s = false ->
  (Q_CACHE < a_qloc_bytes (st_enq s ch) -> a_qglob_bytes (st_enq s ch) + a_qloc_bytes (st_enq s ch) <= Q_MAX) ->
